INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41711, 'Isaiah 28:27', 'Isaiah', 28, 27, 'هغه د شبت او ځيرې د تخمونو د ټکولو دپاره د درمند ټکولو څپر نه کار نه اخلي بلکې د لرګیو نه کار اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_27.mp3', '', 1761754199, 1761754199),
(41712, 'Isaiah 28:28', 'Isaiah', 28, 28, 'هغه د غنمو د درمند په غوبل کولو پوهیږي چې تر کومه وخته هغه غوبل شي چې غنمو ته زیان ونه رسیږي. هغه د اسونو د ګاډۍ څخه کار اخلي ترڅو وکولای شي د ګاډۍ په ارابو باندې د غنمو درمند ښه غوبل کړي چې غلې دانې خرابې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_28.mp3', '', 1761754199, 1761754199),
(41713, 'Isaiah 28:29', 'Isaiah', 28, 29, 'دا هرڅه مطلق قادر څښتن هغه ته ورزده کوي، ځکه چې د هغه نقشې ډېرې لوړې او د حکمت څخه ډکې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah28_verse_29.mp3', '', 1761754199, 1761754199),
(41714, 'Ezekiel 5:1', 'Ezekiel', 5, 1, 'څښتن وویل: «ای فاني انسانه، یوه تېره توره راواخله او د هغې نه د دلاکۍ د چاړې په ځای کار واخله او خپل سر او ږیره ورباندې وخرایه. بیا هغه ویښتان په ترازو کې وتله او په درېو برخو یې ووېشه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_1.mp3', '', 1761754199, 1761754199),
(41715, 'Ezekiel 5:2', 'Ezekiel', 5, 2, 'کله چې د هغې کلابندۍ وخت چې ته یې وړاندې کوې پای ته ورسېدله، نو د هغو ویښتانو یوه برخه په ښار کې وسوځوه. بله برخه یې راواخله او په خپله توره يې ټوټې ټوټې کړه او د ښار ګردچاپېره يې وشینده. درېمه برخه یې د باد مخې ته وشینده او زه به هغه په خپلې تورې سره تعقیب کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_2.mp3', '', 1761754199, 1761754199),
(41716, 'Ezekiel 5:3', 'Ezekiel', 5, 3, 'بیا لږ ویښتان راواخله او د خپلو کالیو په لمنه کې یې پټ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_3.mp3', '', 1761754199, 1761754199),
(41717, 'Ezekiel 5:4', 'Ezekiel', 5, 4, 'له هغو ویښتانو نه بیا لږ څه واخله، په اور کې یې واچوه او ویې سوځوه. دا اور به د اسراییلو ټول قوم ته خپور شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_4.mp3', '', 1761754199, 1761754199),
(41718, 'Ezekiel 5:5', 'Ezekiel', 5, 5, '«زه څښتن تعالی داسې وایم: ‹دا اورشلیم دی. ما هغه د قومونو په منځ کې ځای په ځای کړی او نور هېوادونه ورڅخه ګردچاپېره پراته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_5.mp3', '', 1761754199, 1761754199),
(41719, 'Ezekiel 5:6', 'Ezekiel', 5, 6, 'خو د اورشلیم خلکو زما د حکمونو نه سرکښي وکړه او دا یې وښودله چې هغوی د نورو قومونو نه ډېر بدکاره دي او د خپل شاوخوا هېوادونو نه ډېر نافرمانه دي. هغوی زما حکمونه رد کړي دي او زما د قوانینو څخه یې اطاعت نه دی کړی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_6.mp3', '', 1761754199, 1761754199),
(41720, 'Ezekiel 5:7', 'Ezekiel', 5, 7, 'نو له دې امله څښتن تعالی داسې وایي: ‹تاسو خلکو د نورو قومونو څخه زیاته سرکښي کړې ده او زما د حکمونو او قوانینو څخه مو انکار کړی دی. تاسو حتی د خپل شاوخوا هېوادونو د معیارونو سره سم ژوند نه دی کړی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_7.mp3', '', 1761754199, 1761754199),
(41721, 'Ezekiel 5:8', 'Ezekiel', 5, 8, 'نو ځکه زه څښتن تعالی تاته داسې وایم چې ګوره ای اورشلیمه، زه په خپله ستا دښمن یم. زه به د ټولو قومونو په حضور کې تاته سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_8.mp3', '', 1761754199, 1761754199),
(41722, 'Ezekiel 5:9', 'Ezekiel', 5, 9, 'نو د هغو بدو کارونو له امله چې ستا خلکو کړي دي او زه ورڅخه کرکه کوم، زه به تا ته داسې سزا درکړم چې له دې نه مخکې مې چاته نه ده ورکړې او نه به یې له دې وروسته ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_9.mp3', '', 1761754199, 1761754199),
(41723, 'Ezekiel 5:10', 'Ezekiel', 5, 10, 'نو نتیجه به یې دا شي چې په اورشلیم کې به میندې او پلرونه خپل اولادونه او اولادونه به خپل میندې او پلرونه وخوري. زه به ستا خلکو ته سزا ورکړم او څوک چې ژوندي پاتې شي هغوی به هرې خواته خواره واره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_10.mp3', '', 1761754199, 1761754199),
(41724, 'Ezekiel 5:11', 'Ezekiel', 5, 11, 'نو له دې امله زه څښتن تعالی داسې وایم: ‹زه په خپل ذات باندې قسم خورم، څرنګه چې تاسو په خپلو د کرکې وړ بتانو او کارونو سره زما د عبادت ځای ناپاک کړی دی، نو زه به هم تاسو په بې‌رحمۍ سره له منځه یوسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_11.mp3', '', 1761754199, 1761754199),
(41725, 'Ezekiel 5:12', 'Ezekiel', 5, 12, 'ستا د خلکو یوه برخه به په ښار کې د وبا او قحطۍ له لاسه مړه شي، بله برخه به دې د ښار څخه دباندې په تورو باندې ووژل شي او درېمه برخه به دې هرې خواته خواره واره کړم او زه به هغه په خپلې تورې سره تعقیب کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_12.mp3', '', 1761754199, 1761754199),
(41726, 'Ezekiel 5:13', 'Ezekiel', 5, 13, 'داسې به زما د غضب اور مړ شي او ستا د خلکو په وړاندې به زما قهر سوړ شي. کله چې دا پېښې رامنځته شي، نو ستا خلک به پوه شي چې ما څښتن د هغوی سره خبرې کړې وې او زه د خپل غیرت له امله په قهر شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_13.mp3', '', 1761754199, 1761754199),
(41727, 'Ezekiel 5:14', 'Ezekiel', 5, 14, 'پرته له دې به تا د شاوخوا قومونو په منځ کې او د هرچا په سترګو کې چې له دې ځای څخه تېریږي، وران او رسوا کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_14.mp3', '', 1761754199, 1761754199),
(41728, 'Ezekiel 5:15', 'Ezekiel', 5, 15, 'کله چې زه په قهر او غضب کې تاته سزا درکړم، نو له دې امله به ستا شاوخوا ټول قومونه ووېریږي او هغوی ته به عبرت وي. هغوی به تاته په سپکه سترګه ګوري او ملنډې به درباندې وهي.› دا ما څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_15.mp3', '', 1761754199, 1761754199),
(41729, 'Ezekiel 5:16', 'Ezekiel', 5, 16, 'زه به په تاسو باندې د قحطۍ وژونکي تیرونه درګوزار کړم چې تاسو تباه کړي. قحطي به دومره سخته شي چې ستا خلک به د خوړو د نشتوالي سره مخ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_16.mp3', '', 1761754199, 1761754199),
(41730, 'Ezekiel 5:17', 'Ezekiel', 5, 17, 'زه به ستا په خلکو باندې قحطي نازله کړم او وحشي حیوانات به درولېږم، ترڅو تا او ستا اولادونه له منځه یوسي. وبا او وینه تویول به په تا باندې راشي او خلک به د دښمن په توره ووژل شي. دا زما یعنې د څښتن وینا ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel5_verse_17.mp3', '', 1761754199, 1761754199),
(41731, 'Nehemiah 10:1', 'Nehemiah', 10, 1, 'لومړنی کس چې مهر یې ولګاوه هغه والي یعنې نحمیا د حکلیا زوی ؤ او بیا صدقیا مهر ولګاوه. لاندې خلکو هم مهرونه ولګول:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_1.mp3', '', 1761754199, 1761754199),
(41732, 'Nehemiah 10:28', 'Nehemiah', 10, 28, 'مونږ د اسراییلو نورو خلکو، کاهنانو، لاویانو، د خدای د کور ساتونکو، سندرغاړو، خدمتګارانو او نورو ټولو هغو خلکو چې د خدای د شریعت څخه اطاعت کوي، خپل ځانونه د هغو پردیو قومونو څخه چې زمونږ په خاوره کې اوسیږي، بېل کړل. مونږ د خپلو ښځو او خپلو ټولو هغو زامنو او لورګانو سره چې په دې لوظ پوهیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_28.mp3', '', 1761754199, 1761754199),
(41733, 'Nehemiah 10:29', 'Nehemiah', 10, 29, 'د خپلو مشرانو سره په دې قسم کې یوځای کېږو چې مونږ به د خدای د شریعت سره سم چې خدای د خپل خدمتګار موسی په وسیله راکړی دی خپل ژوند تېروو. مونږ به د خپل څښتن په ټولو حکمونو، قوانینو او شرطونو باندې عمل او د هغو اطاعت به کوو. که چېرې مونږ هغه مات کړو، نو د خدای لعنت دې په مونږ باندې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_29.mp3', '', 1761754199, 1761754199),
(41734, 'Nehemiah 10:30', 'Nehemiah', 10, 30, 'مونږ دا لوظ کوو چې مونږ به خپلې لورګانې د غیریهودیانو زامنو ته نه ورکوو او نه به پرېږدو چې زمونږ زامن د غیریهودیانو د لورګانو سره ودونه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_30.mp3', '', 1761754199, 1761754199),
(41735, 'Nehemiah 10:31', 'Nehemiah', 10, 31, 'که چېرې پردي خلک غلې دانې یا کوم بل شی راوړي چې په مونږ باندې یې د سبت یا په کومه بله سپېڅلې ورځ خرڅ کړي، مونږ به یې ورڅخه وانخلو. په هر اووم کال به په ځمکه کې کرنه نه کوو او خپل ټول پورونه به وبخښو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_31.mp3', '', 1761754199, 1761754199),
(41736, 'Nehemiah 10:32', 'Nehemiah', 10, 32, 'مونږ مسوولیت لرو چې هر کال به د مثقال درېمه برخه سپین زر د خپل خدای د کور د لګښت دپاره ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_32.mp3', '', 1761754199, 1761754199),
(41737, 'Nehemiah 10:33', 'Nehemiah', 10, 33, 'مونږ به د خدای په کور کې د عبادت دپاره دا شیان تیار کړو: سپېڅلې ډوډۍ، د غلو دانو ورځنۍ نذرانه، هغه څاروي چې د قربانیو په توګه هره ورځ سوځول کیږي، د سبت، د نوې میاشتې د اخترونو او نورو اخترونو دپاره سپېڅلې نذرانې، نورې سپېڅلې نذرانې، د اسراییلو د ګناهونو د کفارې نذرانې او نور شیان چې د خدای د کور دپاره ورته اړتیا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_33.mp3', '', 1761754199, 1761754199),
(41738, 'Nehemiah 10:34', 'Nehemiah', 10, 34, 'مونږ یعنې کاهنان او لاویان او زمونږ خلک به هر کال پچه اچوو چې دا څرګنده شي چې کومې طایفې به په ټاکلي وخت زمونږ د خدای کور ته لرګي راوړي، ترڅو د شریعت د شرطونو سره سم هغه سوځېدونکې قربانۍ ورباندې وسوځول شي چې زمونږ څښتن خدای ته وړاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_34.mp3', '', 1761754199, 1761754199),
(41739, 'Nehemiah 10:35', 'Nehemiah', 10, 35, 'مونږ مسوولیت لرو چې هر کال د څښتن کور ته د لومړنیو غلو دانو او د هرې ونې لومړنۍ مېوې د نذرانې په توګه راوړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_35.mp3', '', 1761754199, 1761754199),
(41740, 'Nehemiah 10:36', 'Nehemiah', 10, 36, 'لکه څنګه چې په شریعت کې لیکل شوي دي، مونږ به د خپلو زامنو، غواګانو، وزو او مېږو څخه هر لومړنی زېږول شوی هغه کاهنانو ته راولو چې د خدای په کور کې خدمت کوي او هغه به خدای ته وقف کوو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_36.mp3', '', 1761754199, 1761754199),
(41741, 'Nehemiah 10:37', 'Nehemiah', 10, 37, 'مونږ به د اوړو هغه پېړه چې هر کال د لومړنیو راټولو شویو غلو دانو حاصل څخه تیاره شوې وي او د شرابو، د زیتونو د تېلو او د هر ډول مېوو د حاصل نورې نذرانې هغو کاهنانو ته راوړو چې د خدای په کور کې د ګودامونو مسوولان دي. مونږ به د خپلو ځمکو د حاصلاتو لسمه برخه هغو لاویانو ته چې زمونږ په ښارګوټو کې هغه راټولوي، ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_37.mp3', '', 1761754199, 1761754199),
(41742, 'Nehemiah 10:38', 'Nehemiah', 10, 38, 'د لسمې برخې د راټولولو په وخت کې باید هغه کاهنان چې د هارون د اولادې څخه دي د لاویانو سره وي او لاویان دې د راټول شوي عشر، لسمه برخه د خدای د کور ګودامونو ته یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_38.mp3', '', 1761754199, 1761754199),
(41743, 'Nehemiah 10:39', 'Nehemiah', 10, 39, 'د اسراییلو خلک او لاویان باید د غلو دانو، شرابو او د زیتونو د تېلو اعانې هغو ګودامونو ته راوړي په کومو کې چې د خدای د کور لوښي ساتل کیږي او کاهنان چې خدمت کوي، د خدای د کور ساتونکي او سندرغاړي هلته اوسیږي. مونږ به د خدای د کور په اړه بې پروایي ونه کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah10_verse_39.mp3', '', 1761754199, 1761754199),
(41744, 'Numbers 4:1', 'Numbers', 4, 1, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_1.mp3', '', 1761754199, 1761754199),
(41745, 'Numbers 4:2', 'Numbers', 4, 2, '«د قهاتیانو سرشمېرنه چې د لاویانو د قبیلې یوه برخه ده، طایفه په طایفه او کورنۍ په کورنۍ وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_2.mp3', '', 1761754199, 1761754199),
(41746, 'Numbers 4:3', 'Numbers', 4, 3, 'هغه ټول کسان وشمېرئ چې عمر یې د دېرشو کالو څخه تر پنځوسو کالو پورې وي او په سپېڅلې خېمه کې د کار کولو توان ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_3.mp3', '', 1761754199, 1761754199),
(41747, 'Numbers 4:4', 'Numbers', 4, 4, 'په سپېڅلې خېمه کې د قهاتیانو کار دا دی چې په سپېڅلو شیانو باندې پام وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_4.mp3', '', 1761754199, 1761754199),
(41748, 'Numbers 4:5', 'Numbers', 4, 5, 'کله چې د دې وخت راشي چې کمپ ته حرکت ورکړای شي، نو هارون او د هغه زامن به خېمې ته ورننوځي، هغه پرده به راښکته کړي چې د لوظ د صندوق په مخکې ده او صندوق به ورباندې پټ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_5.mp3', '', 1761754199, 1761754199),
(41749, 'Numbers 4:6', 'Numbers', 4, 6, 'په هغه باندې به د ښې څرمنې پوښ واچوي او په سر باندې به یې یو داسې ټوکر خپور کړي چې پوخ ابي رنګ ولري او بیا به وړونکې میلې په کې ورننباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_6.mp3', '', 1761754199, 1761754199),
(41750, 'Numbers 4:7', 'Numbers', 4, 7, 'هغوی به په هغه مېز باندې چې خدای ته ورباندې ډوډۍ وړاندې کیږي یو ابي ټوکر خپور کړي او په هغه باندې به قابونه، د خوشبویۍ کاسې، د نذرانې دپاره کاسې او هغه منګي کېږدي چې د څښلو د نذرانو دپاره دي. په مېز باندې به تل ډوډۍ پرته وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_7.mp3', '', 1761754199, 1761754199),
(41751, 'Numbers 4:8', 'Numbers', 4, 8, 'هغوی به په دې ټولو باندې یو سور ټوکر خپور کړي، د یوې ښې څرمنې پوښ به ورباندې واچوي او بیا به وړونکې میلې په کې ورننباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_8.mp3', '', 1761754199, 1761754199),
(41752, 'Numbers 4:9', 'Numbers', 4, 9, 'هغوی دې یو ابي ټوکر واخلي او دغه شیان دې ورباندې پټ کړي: څراغدان د څراغونو سره، د هغه پلته پاکوونکي، پتنوسونه او د زیتونو د تېلو ټول لوښي چې د څراغونو دپاره کارول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_9.mp3', '', 1761754199, 1761754199),
(41753, 'Numbers 4:10', 'Numbers', 4, 10, 'هغوی به څراغدان او د هغه ټول سامان د ښې څرمنې په پوښ کې راتاو کړي او په یو وړونکي چوکاټ باندې به یې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_10.mp3', '', 1761754199, 1761754199),
(41754, 'Numbers 4:11', 'Numbers', 4, 11, 'بیا به د سرو زرو د قربانۍ په ځای باندې یو ابي ټوکر خپور کړي، د ښې څرمنې یو پوښ به ورباندې واچوي او بیا به وړونکې میلې په کې ورننباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_11.mp3', '', 1761754199, 1761754199),
(41755, 'Numbers 4:12', 'Numbers', 4, 12, 'هغوی به هغه ټول لوښي چې په سپېڅلي ځای کې ورڅخه کار اخیستل کیږي واخلي او په یو ابي ټوکر کې به یې تاو کړي، د ښې څرمنې یو پوښ به ورباندې واچوي او په یو وړونکي چوکاټ باندې به یې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_12.mp3', '', 1761754199, 1761754199),
(41756, 'Numbers 4:13', 'Numbers', 4, 13, 'د قربانۍ د ځای څخه به ایرې لېرې کړي او په هغه باندې به یو بانجاني ټوکر خپور کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_13.mp3', '', 1761754199, 1761754199),
(41757, 'Numbers 4:14', 'Numbers', 4, 14, 'په هغه ټوکر باندې دې هغه ټول سامان کېږدي چې د قربانۍ په ځای کې ورڅخه کار اخیستل کیږي: لکه د اور لوښي، د غوښې قاشق پنجې، بېلچې او د وینې د شیندلو کاسې. بیا به هغوی ورباندې د ښې څرمنې یو پوښ واچوي او وړونکې میلې به په کې ورننباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_14.mp3', '', 1761754199, 1761754199),
(41758, 'Numbers 4:15', 'Numbers', 4, 15, 'کله چې هارون او د هغه زامن د سپېڅلي سامان او ټولو سپېڅلو موادو د پټولو څخه وزګار شي او کمپ د وړلو دپاره تیار شي، نو قهاتیان دې د دغو شیانو د وړلو دپاره راشي. خو هغوی باید سپېڅلو شیانو ته لاس ورنه وړي که نه، نو مړه به شي. قهاتیان دې هغه شیان انتقال کړي چې په سپېڅلې خېمه کې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_15.mp3', '', 1761754199, 1761754199),
(41759, 'Numbers 4:16', 'Numbers', 4, 16, 'د هارون کاهن زوی العازار دې د دغو شیانو مسوولیت په غاړه واخلي: د څراغونو دپاره د زیتونو تېل، خوشبویي، د عادي غلې دانې نذرانه او د مسح کولو تېل. هغه دې د ټولې سپېڅلې خېمې او هرڅه چې په کې دي، د سپېڅلي سامان او لوښو په شمول د هغو مسوولیت په غاړه واخلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_16.mp3', '', 1761754199, 1761754199),
(41760, 'Numbers 4:17', 'Numbers', 4, 17, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_17.mp3', '', 1761754199, 1761754199),
(41761, 'Numbers 4:20', 'Numbers', 4, 20, 'خو قهاتیان باید دننه لاړ نه شي چې سپېڅلي شیان وګوري، حتی د یوې شېبې دپاره هم. که نه، نو مړه به شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_20.mp3', '', 1761754199, 1761754199),
(41762, 'Numbers 4:21', 'Numbers', 4, 21, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_21.mp3', '', 1761754199, 1761754199),
(41763, 'Numbers 4:22', 'Numbers', 4, 22, '«د جرشونیانو سرشمېرنه چې د لاویانو د قبیلې یوه برخه ده، کورنۍ په کورنۍ او طایفه په طایفه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_22.mp3', '', 1761754199, 1761754199),
(41764, 'Numbers 4:23', 'Numbers', 4, 23, 'هغه ټول کسان چې عمر یې د دېرشو کالو څخه تر پنځوسو کالو پورې وي او په سپېڅلې خېمه کې د کار کولو توان ولري وشمېره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_23.mp3', '', 1761754199, 1761754199),
(41765, 'Numbers 4:24', 'Numbers', 4, 24, 'هغوی به د لاندېنیو شیانو د وړلو مسوولیت په غاړه لري:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_24.mp3', '', 1761754199, 1761754199),
(41766, 'Numbers 4:25', 'Numbers', 4, 25, 'خېمه، د هغې داخلي او باندینی پوښ، د هغې په سر باندې د ښې څرمنې پوښ، د دروازې پرده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_25.mp3', '', 1761754199, 1761754199),
(41767, 'Numbers 4:26', 'Numbers', 4, 26, 'د خېمې او د قربانۍ د ځای د ګردچاپېره حوېلۍ دپاره پردې، د حوېلۍ د دروازې پرده، رسۍ ګانې او هرڅه چې د دې شیانو په ودرولو کې په کاریږي. جرشونیان د دې ټولو شیانو د ساتنې او ترتیبولو مسوولیت په غاړه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_26.mp3', '', 1761754199, 1761754199),
(41768, 'Numbers 4:27', 'Numbers', 4, 27, 'ته او هارون به وګورئ چې جرشونیان دا ټول کارونه تر سره کوي او هر هغه شی چې هارون او د هغه زامنو هغوی ته ورسپارلی دی، وړي که نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_27.mp3', '', 1761754199, 1761754199),
(41769, 'Numbers 4:28', 'Numbers', 4, 28, 'دا د سپېڅلې خېمې په کار کې د جرشونیانو دندې دي. هغوی به دا کار د هارون کاهن د زوی یعنې ایتامار تر لارښوونې لاندې تر سره کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_28.mp3', '', 1761754199, 1761754199),
(41770, 'Numbers 4:29', 'Numbers', 4, 29, 'څښتن موسی ته وویل: «مراریان چې د لاویانو د قبیلې یوه برخه ده طایفه په طایفه او کورنۍ په کورنۍ وشمېره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_29.mp3', '', 1761754199, 1761754199),
(41771, 'Numbers 4:30', 'Numbers', 4, 30, 'هغه ټول کسان چې عمر یې د دېرشو کالو څخه تر پنځوسو کالو پورې وي او په سپېڅلې خېمه کې د کار کولو توان ولري وشمېره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_30.mp3', '', 1761754199, 1761754199),
(41772, 'Numbers 4:31', 'Numbers', 4, 31, 'هغوی به د چوکاټونو، اړمونو، ستنو او خېمې د پایو د وړلو مسوولیت ولري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_31.mp3', '', 1761754199, 1761754199),
(41773, 'Numbers 4:32', 'Numbers', 4, 32, 'او همدارنګه د خېمې د ګردچاپېره حوېلۍ د ستنو، پایو، مېخونو، رسۍ ګانو او هغو ټولو شیانو چې د هغو په ودرولو کې په کاریږي. هر سړی به د ځانګړو شیانو د وړلو مسوولیت په غاړه ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_32.mp3', '', 1761754199, 1761754199),
(41774, 'Numbers 4:33', 'Numbers', 4, 33, 'دا د سپېڅلې خېمې په کار کې د مراریانو دندې دي. هغوی به دا کار د هارون کاهن د زوی یعنې ایتامار تر لارښوونې لاندې تر سره کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_33.mp3', '', 1761754199, 1761754199),
(41775, 'Numbers 4:49', 'Numbers', 4, 49, 'څنګه چې څښتن موسی ته حکم کړې ؤ، هر سړی وشمېرل شو او هر یو ته د خدمت کولو یا د وړلو د دندې مسوولیت وسپارل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers4_verse_49.mp3', '', 1761754199, 1761754199),
(41776, 'Ezekiel 24:1', 'Ezekiel', 24, 1, 'زمونږ د جلاوطنۍ د نهم کال د لسمې میاشتې په لسمه ورځ څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_1.mp3', '', 1761754199, 1761754199),
(41777, 'Ezekiel 24:2', 'Ezekiel', 24, 2, '«ای فاني انسانه، نننۍ نېټه ولیکه. هو همدا ورځ، ځکه چې د بابل پاچا نن ورځ د اورشلیم په کلابند کولو باندې پیل کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_2.mp3', '', 1761754199, 1761754199),
(41778, 'Ezekiel 24:3', 'Ezekiel', 24, 3, 'دې سرکښه قوم ته دا مثال ووایه چې زه څښتن تعالی یې هغوی ته بیانوم: ‹دېګی کېږدئ په اور باندې او په کې واچوئ اوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_3.mp3', '', 1761754199, 1761754199),
(41779, 'Ezekiel 24:4', 'Ezekiel', 24, 4, 'په کې واچوئ د غوښې ښې ټوټې د ورانه او د اوږو غوښه هغه کړئ ډک د ډېرو ښو غوښو نه چې لري هډوکي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_4.mp3', '', 1761754199, 1761754199),
(41780, 'Ezekiel 24:5', 'Ezekiel', 24, 5, 'واخلئ رمې نه ډېر ښه پسه کېږدئ لرګي د دېګي لاندې پرېږدئ چې ښه جوش شي اوبه کړئ پاخه غوښه او هډوکي›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_5.mp3', '', 1761754199, 1761754199),
(41781, 'Ezekiel 24:6', 'Ezekiel', 24, 6, 'څښتن تعالی داسې وایي: ‹افسوس د خونړي ښار په حال! دا د داسې زنګ وهلي دېګي په شان دی چې هېڅکله نه پاکیږي. ټوټه ټوټه غوښه ورڅخه وباسئ چې یوه ټوټه هم په کې پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_6.mp3', '', 1761754199, 1761754199),
(41782, 'Ezekiel 24:7', 'Ezekiel', 24, 7, 'ځکه د اورشلیم خلکو په ښار کې بې‌ګناه خلک ووژل، خو وینه یې په ځمکې باندې تویه نه شوه چې په خاورو کې پټه شوې وای، هغه په ګټ باندې تویه شوه چې ټول یې وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_7.mp3', '', 1761754199, 1761754199),
(41783, 'Ezekiel 24:8', 'Ezekiel', 24, 8, 'د دې دپاره چې زه په قهر شم او بدل واخلم، نو هغه وینه مې په هغه ګټ باندې پرېښودله چې پټه نه شي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_8.mp3', '', 1761754199, 1761754199),
(41784, 'Ezekiel 24:9', 'Ezekiel', 24, 9, 'نو څښتن تعالی داسې وایي: «افسوس د خونړي ښار په حال! زه به هم د هغه لاندې د سوځولو دپاره د لرګيو ډېرۍ جوړه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_9.mp3', '', 1761754199, 1761754199),
(41785, 'Ezekiel 24:10', 'Ezekiel', 24, 10, 'نو ډېر لرګي راوړئ او اور بل کړئ! غوښه ښه پخه کړئ، مساله په کې واچوئ او تر هغې پورې يې وخوټوئ چې اوبه یې وچې شي او هډوکي وسوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_10.mp3', '', 1761754199, 1761754199),
(41786, 'Ezekiel 24:11', 'Ezekiel', 24, 11, 'بیا هغه د برنجو خالي دېګی د سکارو په اور باندې کېږدئ او هغه پرېږدئ چې تک سور شي. بیا به د هغه زنګ وسوځي او هغه به بېرته پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_11.mp3', '', 1761754199, 1761754199),
(41787, 'Ezekiel 24:12', 'Ezekiel', 24, 12, 'خو ما بې‌ګټې ځان ستړی کړ، ځکه دېګی لا پاک شوی نه دی. هغه چټلي په اور کې بیا واچوئ چې پاکه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_12.mp3', '', 1761754199, 1761754199),
(41788, 'Ezekiel 24:13', 'Ezekiel', 24, 13, 'ای اورشلیمه، ته خپلې شهوت پرستۍ ناپاکه کړی یې. سره له دې ما هڅه وکړه چې تا پاک کړم، خو ته هماغسې ناپاکه پاتې شوې. ترڅو پورې چې تا زما د قهر زور نه وي لیدلی، ته به بېرته پاک نه شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_13.mp3', '', 1761754199, 1761754199),
(41789, 'Ezekiel 24:14', 'Ezekiel', 24, 14, 'ما څښتن داسې وویل. د عمل وخت رارسېدلی دی. زه به د سزا ورکولو څخه ډډه ونه کړم، نه به درباندې زړه وسوځوم او نه به درباندې رحم وکړم. بلکې تاسو چې کوم کارونه کړي دي، د هغو له امله به تاسو محاکمه کړم. زه څښتن داسې وایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_14.mp3', '', 1761754199, 1761754199),
(41790, 'Ezekiel 24:15', 'Ezekiel', 24, 15, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_15.mp3', '', 1761754199, 1761754199),
(41791, 'Ezekiel 24:16', 'Ezekiel', 24, 16, '«ای فاني انسانه، زه به د سترګو په رپ کې ستا ښځه چې په تا باندې ډېره ګرانه او د سترګو تور دی، ستا نه واخلم. خو ته ویر مه کوه، مه ژاړه او اوښکې مه تویوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_16.mp3', '', 1761754199, 1761754199),
(41792, 'Ezekiel 24:17', 'Ezekiel', 24, 17, 'ستا اسوېلي باید ونه اورېدل شي. له غمه سرتور سر او لوڅې پښې مه ګرځه. له غمه خپل مخ مه پټوه او د مړي د کور ډوډۍ مه خوره.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_17.mp3', '', 1761754199, 1761754199),
(41793, 'Ezekiel 24:18', 'Ezekiel', 24, 18, 'نو بیا مې د سهار په وخت د خلکو سره خبرې وکړې او ماښام زما ښځه مړه شوه. بله ورځ مې هماغسې وکړل لکه څنګه چې څښتن راته ویلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_18.mp3', '', 1761754199, 1761754199),
(41794, 'Ezekiel 24:19', 'Ezekiel', 24, 19, 'خلکو زما نه پوښتنه وکړه: «دا کارونه مونږ ته څه معنی لري او ولې مونږ ته نه وایې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_19.mp3', '', 1761754199, 1761754199),
(41795, 'Ezekiel 24:20', 'Ezekiel', 24, 20, 'نو ما هغوی ته وویل: «څښتن زما سره خبرې وکړې او راته ویې ویل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_20.mp3', '', 1761754199, 1761754199),
(41796, 'Ezekiel 24:21', 'Ezekiel', 24, 21, 'چې څښتن تعالی تاسو اسراییلیانو ته دا پیغام لري: ‹زه اوس د خپل سپېڅلي عبادت ځای سپکاوی کوم او هغه د قوت مقام چې تاسو ورباندې ویاړ کاوه، ورانوم. ستاسو د سترګو تور او د مینې د پام وړ ځای تباه کوم. ستاسو زامن او لورګانې چې په اورشلیم کې پاتې شوي دي، هغوی ټول به په جنګ کې ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_21.mp3', '', 1761754199, 1761754199),
(41797, 'Ezekiel 24:22', 'Ezekiel', 24, 22, 'بیا به تاسو زما په شان هماغسې وکړئ. له غمه به خپل مخ نه پټوئ او نه به د مړي د کور ډوډۍ خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_22.mp3', '', 1761754199, 1761754199),
(41798, 'Ezekiel 24:23', 'Ezekiel', 24, 23, 'تاسو به سرتور سر او لوڅې پښې نه ګرځئ او نه به ویر او ژړا کوئ. تاسو به یو بل ته فریادونه کوئ او د خپلو ګناهونو له امله به کمزوري کېږئ، ترڅو له منځه لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_23.mp3', '', 1761754199, 1761754199),
(41799, 'Ezekiel 24:24', 'Ezekiel', 24, 24, 'بیا به حزقیال ستاسو دپاره یو مثال وي چې پیروي ورڅخه وکړئ، هغه چې څه کوي تاسو به هم هماغسې کوئ. څښتن وایي چې کله داسې وشي، نو تاسو به پوه شئ چې زه څښتن تعالی یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_24.mp3', '', 1761754199, 1761754199),
(41800, 'Ezekiel 24:25', 'Ezekiel', 24, 25, 'څښتن وویل: «ای فاني انسانه، زه به د هغوی نه هغه قوي کلا چې هغوی ورباندې ویاړ او خوشحالي کوي او د هغه په لیدلو خوند اخلي، واخلم او د هغوی نه به زامن او لورګانې هم واخلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_25.mp3', '', 1761754199, 1761754199),
(41801, 'Ezekiel 24:26', 'Ezekiel', 24, 26, 'په هغه ورځ چې زه دا کار کوم، نو څوک چې د دې تباهۍ نه تښتېدلی وي، هغه به راشي او په دې هکله به خبر ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_26.mp3', '', 1761754199, 1761754199),
(41802, 'Ezekiel 24:27', 'Ezekiel', 24, 27, 'په هماغه ورځ به ته بیا خبرې وکولای شې او نور به ګونګی پاتې نه شې. نو کوم څه چې ستا سره پېښیږي، هغه به د خلکو دپاره یوه نښه شې او هغوی به په دې پوه شي چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel24_verse_27.mp3', '', 1761754199, 1761754199),
(41803, 'Ezekiel 13:1', 'Ezekiel', 13, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_1.mp3', '', 1761754199, 1761754199),
(41804, 'Ezekiel 13:2', 'Ezekiel', 13, 2, '«ای فاني انسانه، د اسراییلو د هغو پیغمبرانو په ضد نبوت وکړه چې د خپل ځان نه نبوت کوي. هغوی ته ووایه چې د څښتن کلام ته غوږ ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_2.mp3', '', 1761754199, 1761754199),
(41805, 'Ezekiel 13:3', 'Ezekiel', 13, 3, 'څښتن تعالی داسې وایي: ‹افسوس د دې کم‌عقلو پیغمبرانو په حال! هغوی د خپلو ځانونو نه الهام ورکوي او هغه رویاګانې یې چې نه دي لیدلې، بیانوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_3.mp3', '', 1761754199, 1761754199),
(41806, 'Ezekiel 13:4', 'Ezekiel', 13, 4, 'ای د اسراییلو خلکو، ستاسو پیغمبران د هغو ګیدړانو په شان دي چې د ښار په کنډوالو کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_4.mp3', '', 1761754199, 1761754199),
(41807, 'Ezekiel 13:5', 'Ezekiel', 13, 5, 'هغو پیغمبرانو تاسو اسراییلیانو سره مرسته ونه کړه چې د ښار هغه دېوالونه بېرته جوړ کړي چې غورځېدلي دي. دا کار باید ترسره شي، ترڅو په هغه وخت کې چې زه څښتن ستاسو دښمنان پرېږدم چې په تاسو باندې حمله وکړي، ستاسو دېوالونه قوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_5.mp3', '', 1761754199, 1761754199),
(41808, 'Ezekiel 13:6', 'Ezekiel', 13, 6, 'د هغوی رویاګانې غلطې دي او د هغوی پېشګویانې دروغ دي. هغوی دا دعوه کوي چې زما د پیغام په هکله خبرې کوي، خو هغوی ما نه دي لېږلي. خو بیاهم هغوی په دې تمه دي چې خبرې به یې رښتیا شي!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_6.mp3', '', 1761754199, 1761754199),
(41809, 'Ezekiel 13:7', 'Ezekiel', 13, 7, 'زه هغوی ته وایم: ‹تاسو چې کومې رویاګانې وینئ هغه بې‌ارزښته دي او تاسو چې کومې پېشګویانې کوئ هغه دروغ دي. تاسو وایئ چې دا زما خبرې دي، خو ما تاسو سره خبرې نه دي کړي!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_7.mp3', '', 1761754199, 1761754199),
(41810, 'Ezekiel 13:8', 'Ezekiel', 13, 8, 'نو څښتن تعالی هغوی ته داسې وایي: ‹ستاسو خبرې بې‌ارزښته دي او ستاسو رویاګانې دروغ دي. نو له دې امله زه څښتن تعالی ستاسو په ضد یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel13_verse_8.mp3', '', 1761754199, 1761754199);